.detail-head { display: flex; justify-content: space-between; gap: 14px; padding: 20px 22px 0; }
.detail-head h2 { margin: 4px 0 4px; font-size: 22px; }
.detail-head .sub { margin: 0; }
.close { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 7px 12px; height: fit-content; }
.detail-section { padding: 16px 22px 20px; border-top: 1px solid var(--line); margin-top: 16px; }
.equation { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 12px; }
.equation div { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 9px 11px; }
.equation span { display: block; font-size: 12px; color: var(--muted); }
.equation b { font-size: 15px; }
.why { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; font-size: 13.5px; color: var(--muted); }
