.steps .cost { color: var(--muted); font-size: 13px; }
.foot { color: var(--faint); font-size: 12.5px; padding: 4px 2px; }
@media (max-width: 760px) {
  .facts { grid-template-columns: repeat(2, 1fr); }
  .lede h1 { font-size: 21px; }
  .equation { grid-template-columns: repeat(2, 1fr); }
  .field input, .field select { min-width: 0; width: 100%; }
}
